import dayjs, { Dayjs } from 'dayjs';
import { ViewModeConfig } from './view-modes/utils';
import { DateValue } from './types';

import utc from 'dayjs/plugin/utc';
import timezone from 'dayjs/plugin/timezone';
import advancedFormat from 'dayjs/plugin/advancedFormat';
import quarterOfYear from 'dayjs/plugin/quarterOfYear';
import { TimezoneInfo } from '@src/shared/timezone';
import { Locale } from '@fe-infra/keystone-locales';
import { cacheOrUpdate } from '@src/shared/perf/cache';

dayjs.extend(utc);
dayjs.extend(timezone);
dayjs.extend(advancedFormat);
dayjs.extend(quarterOfYear);

export const upperFirst = (str: string, locale: string) => str.charAt(0).toLocaleUpperCase(locale) + str.slice(1);

export function utcOffsetToLabel(utcOffset: number) {
  return `UTC${utcOffset >= 0 ? '+' : '-'}${String(Math.floor(Math.abs(utcOffset / 60))).padStart(
    2,
    '0',
  )}:${String(Math.abs(utcOffset % 60)).padStart(2, '0')}`;
}

export type DatePeriod = 'month' | 'year' | 'decade';

export function startOfPeriod(date: Dayjs, period: DatePeriod) {
  switch (period) {
    case 'month':
    case 'year':
      return date.startOf(period);
    case 'decade': {
      const decade = Math.floor(date.year() / 10);
      return date.startOf('year').year(decade * 10);
    }
    default:
      return date;
  }
}

export function isOutsidePeriod(date: Dayjs, viewDate: Dayjs, period: DatePeriod) {
  switch (period) {
    case 'month':
    case 'year':
      return !date.isSame(viewDate, period);
    case 'decade': {
      const decade = Math.floor(viewDate.year() / 10);
      const year = date.year();
      return year < decade * 10 || year >= (decade + 1) * 10;
    }
    default:
      return false;
  }
}

export function dayjsToNativeDate(dayjs: Dayjs) {
  const year = dayjs.year();
  const month = dayjs.month();
  const day = dayjs.date();
  const hour = dayjs.hour();
  const minute = dayjs.minute();
  const second = dayjs.second();
  const millisecond = dayjs.millisecond();
  return new Date(year, month, day, hour, minute, second, millisecond);
}

const localizedMonthFormatter = cacheOrUpdate(
  'en',
  (locale: Locale) => new Intl.DateTimeFormat(locale, { month: 'long' }),
);
export function getLocalizedMonth(date: Date, locale: Locale = 'en') {
  return upperFirst(localizedMonthFormatter(locale).format(date), locale);
}

export function getDecadeLabelOfYear(year: number) {
  const decade = year - (year % 10);
  return `${decade} – ${decade + 9}`;
}

const isYearFirstCached = cacheOrUpdate('en', (locale: Locale) => {
  try {
    const testDate = new Date(2024, 10, 1); // Use a month with a distinct name (Nov)
    const formatted = new Intl.DateTimeFormat(locale, { year: 'numeric', month: 'short' }).format(testDate);
    const yearIndex = formatted.indexOf('2024');
    const monthFormatted = new Intl.DateTimeFormat(locale, { month: 'short' }).format(testDate);
    const monthIndex = formatted.indexOf(monthFormatted);

    if (yearIndex !== -1 && monthIndex !== -1) {
      return yearIndex < monthIndex;
    }

    return yearIndex !== -1 && yearIndex < formatted.length / 2;
  } catch (e) {
    return false;
  }
});

export function isYearFirst(locale: Locale = 'en'): boolean {
  return isYearFirstCached(locale);
}

export function mergeDateByUnit(
  currentDate: Dayjs | null | undefined,
  incomingDate: Dayjs,
  unit: ViewModeConfig['unit'],
): Dayjs {
  if (!currentDate) {
    return incomingDate;
  }

  let mergedDate = currentDate;

  if (unit !== 'year') {
    mergedDate = mergedDate.set('year', incomingDate.get('year'));
  }
  if (unit !== 'month') {
    mergedDate = mergedDate.set('month', incomingDate.get('month'));
  }
  if (unit !== 'quarter') {
    // quarter have been set by the `unit !== 'month'` case
    const unitToSet = unit === 'day' ? 'date' : unit;
    mergedDate = mergedDate.set(unitToSet, incomingDate.get(unitToSet));
  }

  return mergedDate;
}

export function addPeriodToDate(date: Dayjs, value: number, period: DatePeriod) {
  if (period === 'decade') {
    const YEARS_IN_A_DECADE = 10;
    return date.add(value * YEARS_IN_A_DECADE, 'year');
  } else {
    return date.add(value, period);
  }
}

function extractQuarterFromDate(value: DateValue, format: string) {
  if (typeof format === 'string' && format.includes('Q')) {
    const match = String(value).match(/Q([1-4])/i);
    if (match && match[1]) {
      const quarterNumber = parseInt(match[1], 10);
      const strippedFormat = format.replace(/\[Q\]Q|Q/g, '').trim();
      const strippedValue = String(value)
        .replace(/Q[1-4]/i, '')
        .trim();
      return { quarterNumber, strippedFormat, strippedValue };
    }
  }
  return null;
}

function createDayjsFromQuarterInfo(
  dateValue: DateValue,
  format: string,
  createDayjsFn: (val: string | DateValue, fmt: string) => Dayjs,
) {
  const quarterInfo = extractQuarterFromDate(dateValue, format);
  if (quarterInfo) {
    const { quarterNumber, strippedFormat, strippedValue } = quarterInfo;
    const parsedDate = createDayjsFn(strippedValue, strippedFormat);

    if (parsedDate.isValid()) {
      return parsedDate.quarter(quarterNumber);
    }
  }

  return createDayjsFn(dateValue, format);
}

function parseDateValueInIANATimezone(dateValue: DateValue, format: string, ianaTimezoneId?: string) {
  return createDayjsFromQuarterInfo(dateValue, format, (val, fmt) =>
    ianaTimezoneId ? dayjs.tz(val, fmt, ianaTimezoneId) : dayjs(val, fmt),
  );
}

export function dateValueToDayjs(
  value: DateValue | null | undefined,
  format: string,
  timezone: TimezoneInfo,
): Dayjs | null {
  if (!value) {
    return null;
  }

  if (timezone && typeof timezone.utcOffset === 'number') {
    // the `.utcOffset()` of dayjs will bring extremely buggy behavior when do `.add()`
    // so we always convert it to utc without offset for internal calculation
    return createDayjsFromQuarterInfo(value, format, (val, fmt) => dayjs.utc(val, fmt));
  } else {
    return parseDateValueInIANATimezone(value, format, timezone?.id);
  }
}

/** Gets the current time ("now") as a Day.js object within the context of the specified timezone. */
export function getNow(timezone: TimezoneInfo): Dayjs {
  if (timezone && typeof timezone.utcOffset === 'number') {
    // the `.utcOffset()` of dayjs will bring extremely buggy behavior when do `.add()`
    // so we always convert it to utc without utcOffset for internal calculation
    return dayjs.utc().add(timezone.utcOffset, 'minute');
  } else {
    return dayjs.tz(undefined, timezone?.id);
  }
}

const i18nRelativeTimeFormatter = cacheOrUpdate(
  'en-US',
  (locale) => new Intl.RelativeTimeFormat(locale, { numeric: 'auto' }),
);
export function i18nRelativeTime(value: number, unit: Intl.RelativeTimeFormatUnit, locale = 'en-US') {
  return upperFirst(i18nRelativeTimeFormatter(locale).format(value, unit), locale);
}

interface WeekInfo {
  firstDay: 1 | 2 | 3 | 4 | 5 | 6 | 7;
  weekend: number[];
  minimalDays: number;
}
interface IntlLocaleNext extends Intl.Locale {
  getWeekInfo?: () => WeekInfo;
  weekInfo?: WeekInfo;
}

const getWeekInfo = cacheOrUpdate('en-US', (locale): WeekInfo | undefined => {
  const intlLocale: IntlLocaleNext = new Intl.Locale(locale);
  return intlLocale.getWeekInfo?.() || intlLocale.weekInfo;
});

export function getFirstDayOfWeek(locale = 'en-US') {
  return getWeekInfo(locale)?.firstDay || 1;
}

export function getWeeksInMonth(date: Dayjs, firstDayOfWeek: WeekInfo['firstDay']) {
  const firstDayOfWeekInDayjsFormat = firstDayOfWeek % 7;
  const firstDayOfMonth = date.startOf('month');
  const daysInMonth = date.daysInMonth();
  const offset = (firstDayOfMonth.day() - firstDayOfWeekInDayjsFormat + 7) % 7;

  return Math.ceil((offset + daysInMonth) / 7);
}

export const LOCAL_TIMEZONE = Intl.DateTimeFormat().resolvedOptions().timeZone;
